/** @type {import('next').NextConfig} */
const nextConfig = {
  // Ausgabeverzeichnis umschaltbar (wie oekovolt.de): Build-Verifikation läuft
  // mit NEXT_DIST_DIR=.next-verify neben einem laufenden Server.
  distDir: process.env.NEXT_DIST_DIR || ".next",
  trailingSlash: false,
  compress: true,
  poweredByHeader: false,

  async headers() {
    const sicherheit = [
      { key: "X-Content-Type-Options", value: "nosniff" },
      { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
      { key: "X-Frame-Options", value: "SAMEORIGIN" },
      { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(self)" },
    ];
    return [
      { source: "/:path*", headers: sicherheit },
      // Portal und Login nie in Suchmaschinen, nie zwischenspeichern
      { source: "/portal/:path*", headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow" }, { key: "Cache-Control", value: "no-store" }] },
    ];
  },
};

export default nextConfig;
import { NextResponse } from "next/server";

// WordPress-Artefakte, die es auf oekovolt.de nicht mehr gibt und auch nie
// wieder geben wird. 410 Gone (statt 404) signalisiert Google endgueltig
// "entfernt" -> die URLs fallen schneller aus dem Index bzw. aus dem
// Search-Console-Bericht als bei einem 404.
const GONE_PATTERNS = [
  /^\/wp-login\.php/,
  /^\/wp-admin(\/|$)/,
  /^\/wp-content\//,
  /^\/wp-includes\//,
  /^\/wp-json(\/|$)/,
  /^\/xmlrpc\.php/,
  /^\/wp-cron\.php/,
  /^\/wp-signup\.php/,
  /^\/wp-trackback\.php/,
  // Alte WordPress-Permalinks ohne Rewrite (z. B. /index.php/2019/…)
  /^\/index\.php(\/|$)/,
  /\/feed\/?$/,
];

export function middleware(request) {
  const { pathname } = request.nextUrl;

  for (const pattern of GONE_PATTERNS) {
    if (pattern.test(pathname)) {
      return new NextResponse("410 Gone", {
        status: 410,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "X-Robots-Tag": "noindex",
          "Cache-Control": "public, max-age=86400",
        },
      });
    }
  }

  return NextResponse.next();
}

// Middleware laeuft nur fuer diese Pfade, nicht bei jedem Request.
export const config = {
  matcher: [
    "/wp-login.php",
    "/wp-cron.php",
    "/wp-signup.php",
    "/wp-trackback.php",
    "/xmlrpc.php",
    "/index.php",
    "/index.php/:path*",
    "/wp-admin/:path*",
    "/wp-content/:path*",
    "/wp-includes/:path*",
    "/wp-json/:path*",
    "/feed",
    "/:path*/feed",
  ],
};
// lib/apiBaseUrl.js

// API Configuration from environment variables
const SERVER = process.env.SERVER;
const API_KEY = process.env.API_KEY;
const API_SECRET = process.env.API_SECRET;

export const API_BASE_URL = `${SERVER}/api/method/`;

export function getApiHeaders() {
    if (!API_KEY || !API_SECRET) {
        console.error('Missing API credentials in environment variables');
        throw new Error('API credentials not configured');
    }

    const headers = new Headers();
    headers.append('Authorization', `token ${API_KEY}:${API_SECRET}`);
    headers.append('Content-Type', 'application/json');
    return headers;
}

// Optional: Helper function to check if API is configured
export function isApiConfigured() {
    return !!(API_KEY && API_SECRET);
}// src/lib/backendFehler.js
//
// Turns a failed Frappe response into a short German message the visitor can understand.
// Only validation messages (written by the backend for users) are passed on –
// tracebacks, module paths and other internals stay in the server log.
//
// Result codes for the browser:
//   409 vergeben    – appointment slot was booked in the meantime
//   422 validierung – the backend rejected an input (message says which)
//   429 zu_viele    – rate limit
//   502 backend     – backend not reachable / internal error

export const NICHT_ERREICHBAR = "Der Server ist vorübergehend nicht erreichbar";

const ZU_VIELE = "Zu viele Anfragen in kurzer Zeit – bitte warten Sie einen Moment";

/** Human-readable message of a Frappe ValidationError, or "" */
function validierungsText(daten) {
  if (!/ValidationError|MandatoryError/.test(String(daten?.exc_type || ""))) return "";

  let text = "";
  try {
    const liste = JSON.parse(daten._server_messages || "[]");
    text = JSON.parse(liste[0] || "{}").message || "";
  } catch {
    // _server_messages missing or not JSON – fall back to the exception line
  }
  if (!text && typeof daten.exception === "string") {
    text = daten.exception.replace(/^[\w.]*Error:\s*/, "");
  }
  return text.replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim().slice(0, 200);
}

/**
 * Reads the error body once (JSON or text), logs it on the server and returns
 * { status, body } for NextResponse.json(body, { status }).
 */
export async function backendFehler(response, kontext) {
  const text = await response.text().catch(() => "");
  let daten;
  try {
    daten = JSON.parse(text);
  } catch {
    daten = { message: text.slice(0, 500) };
  }
  console.error(`${kontext}: backend returned ${response.status}`, daten);

  const hinweis = validierungsText(daten);
  if (/nicht mehr verfügbar/i.test(hinweis)) {
    return { status: 409, body: { error: hinweis, code: "vergeben" } };
  }
  if (hinweis) {
    return { status: 422, body: { error: hinweis, code: "validierung" } };
  }
  if (response.status === 429) {
    return { status: 429, body: { error: ZU_VIELE, code: "zu_viele" } };
  }
  return { status: 502, body: { error: NICHT_ERREICHBAR, code: "backend" } };
}
// src/lib/ipAdresse.js
//
// IP-Adresse des Besuchers für den Nachweis von Anfragen/Einwilligungen (Feld „ip_adresse“ in Frappe).
// Immer serverseitig ermitteln – nie einen Wert aus dem Formular übernehmen.

/** IP-Adresse aus der Anfrage (hinter Proxy/Load-Balancer aus X-Forwarded-For bzw. X-Real-IP). */
export function ipAdresse(request) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || request.headers.get("x-real-ip")?.trim() || "";
  return /^[0-9a-f.:]{3,45}$/i.test(ip) ? ip : "";
}
// Serverseitige Prüfung der Kampagnen-Zuordnung (siehe src/lib/herkunft.js).

const KANAELE = ["Anzeige", "Social Media", "E-Mail", "Offline/QR", "Kampagne", "Suchmaschine", "KI-Assistent", "Verweis", "Direkt"];
const VERBOTEN = new Set(["<", ">", '"', "'", "`"]);

/** Steuerzeichen und HTML-relevante Zeichen entfernen, kürzen. */
const text = (v, n) =>
  [...String(v ?? "")]
    .filter((z) => z.codePointAt(0) >= 32 && !VERBOTEN.has(z))
    .join("")
    .trim()
    .slice(0, n);
const pfad = (v) => (/^\/[\w\-/.%~]*$/.test(String(v || "")) ? String(v).slice(0, 200) : "");

/** Liefert Frappe-Felder für die Herkunft oder {} */
export function herkunftFelder(h) {
  if (!h || typeof h !== "object") return {};
  return {
    herkunft_kanal: KANAELE.includes(h.kanal) ? h.kanal : "",
    utm_source: text(h.utm_source, 100),
    utm_medium: text(h.utm_medium, 100),
    utm_campaign: text(h.utm_campaign, 100),
    utm_term: text(h.utm_term, 100),
    utm_content: text(h.utm_content, 100),
    herkunft_referrer: text(h.referrer, 120).replace(/[^a-z0-9.\-]/gi, ""),
    einstiegsseite: pfad(h.einstieg),
  };
}

/** Kompakte Zeile für die Übergangslösung über Kontaktanfragen. */
export function herkunftZeile(h) {
  const f = herkunftFelder(h);
  const teile = [
    f.herkunft_kanal && `Kanal: ${f.herkunft_kanal}`,
    f.utm_source && `Quelle: ${f.utm_source}`,
    f.utm_medium && `Medium: ${f.utm_medium}`,
    f.utm_campaign && `Kampagne: ${f.utm_campaign}`,
    f.herkunft_referrer && `Verweis: ${f.herkunft_referrer}`,
    f.einstiegsseite && `Einstieg: ${f.einstiegsseite}`,
  ].filter(Boolean);
  return teile.length ? `[Herkunft] ${teile.join(" · ")}` : "";
}
// src/lib/herkunft.js
//
// Kampagnen-Zuordnung für Anfragen – bewusst OHNE Cookies und OHNE Browserspeicher:
// Beim ersten Seitenaufruf werden UTM-Parameter, verweisende Domain und Einstiegsseite
// im Arbeitsspeicher der geöffneten Website gehalten (bleibt bei Navigation innerhalb der Seite
// erhalten, endet beim Schließen/Neuladen). Übertragen wird nur zusammen mit einer Anfrage.

let erfasst = null;

const UTM = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
const kurz = (v, n = 100) => String(v || "").replace(/[^\p{L}\p{N} _.\-/:+|]/gu, "").slice(0, n);

function eigeneDomain(host) {
  return /(^|\.)oekoinvest\.(com|at|de|ch)$/.test(host) || host === location.host;
}

/** Einmalig beim ersten Laden aufrufen (HerkunftErfassen in LayoutWrapper). */
export function herkunftErfassen() {
  if (typeof window === "undefined" || erfasst) return;
  const url = new URL(window.location.href);
  const utm = Object.fromEntries(UTM.map((k) => [k, kurz(url.searchParams.get(k))]).filter(([, v]) => v));

  let referrer = "";
  try {
    const r = document.referrer ? new URL(document.referrer) : null;
    if (r && !eigeneDomain(r.host)) referrer = r.host.replace(/^www\./, "");
  } catch {
    /* ungültig */
  }

  // Einmal-Tokens nie übernehmen
  const einstieg = url.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200);
  erfasst = { ...utm, referrer, einstieg, zeit: new Date().toISOString() };
}

/** Kanal grob klassifizieren (für Auswertungen). */
function kanal(h) {
  const medium = (h.utm_medium || "").toLowerCase();
  if (h.utm_source || h.utm_medium) {
    if (/cpc|ppc|paid|ads?$/.test(medium)) return "Anzeige";
    if (/social/.test(medium)) return "Social Media";
    if (/mail|newsletter/.test(medium)) return "E-Mail";
    if (/qr|print|flyer|offline/.test(medium)) return "Offline/QR";
    return "Kampagne";
  }
  const r = h.referrer || "";
  if (!r) return "Direkt";
  if (/google\.|bing\.|duckduckgo\.|ecosia\.|yahoo\.|qwant\./.test(r)) return "Suchmaschine";
  if (/chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google|copilot\.microsoft/.test(r)) return "KI-Assistent";
  if (/facebook\.|instagram\.|linkedin\.|xing\.|t\.co$|x\.com|threads\.net|mastodon|social\.|youtube\./.test(r)) return "Social Media";
  return "Verweis";
}

/** Daten zum Mitsenden mit einer Anfrage. `seite` = aktuelle Seite. */
export function herkunft() {
  if (typeof window === "undefined") return null;
  if (!erfasst) herkunftErfassen();
  const h = erfasst || {};
  return { ...h, kanal: kanal(h), seite: window.location.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200) };
}

/** Kompakte Textzeile für Backends ohne eigene Felder (z. B. bestehende Kontaktanfrage). */
export function herkunftText(h = herkunft()) {
  if (!h) return "";
  const teile = [
    `Kanal: ${h.kanal}`,
    h.utm_source && `Quelle: ${h.utm_source}`,
    h.utm_medium && `Medium: ${h.utm_medium}`,
    h.utm_campaign && `Kampagne: ${h.utm_campaign}`,
    h.utm_term && `Keyword: ${h.utm_term}`,
    h.referrer && `Verweis: ${h.referrer}`,
    h.einstieg && `Einstieg: ${h.einstieg}`,
    h.seite && `Seite: ${h.seite}`,
  ].filter(Boolean);
  return `[Herkunft] ${teile.join(" · ")}`;
}
"use client";
import Navbar from "@/components/Navbar/navbar";
import Footer from "@/components/Reusable/footer";
import dynamic from "next/dynamic";
import { usePathname } from "next/navigation";
import { useEffect } from "react";
import { herkunftErfassen } from "@/lib/herkunft";
import RevealObserver from "@/components/ui/RevealObserver";
import MobileCta from "@/components/Reusable/MobileCta";

// const GoogleTagManager = dynamic(
//   () => import("@next/third-parties/google").then((m) => m.GoogleTagManager),
//   { ssr: false }
// );

const CookieComponentLazy = dynamic(() => import("@/components/Cookies/cookiecomponent"), { ssr: false });
const ToTopButtonLazy = dynamic(() => import("@/components/Home/BackToTop"), { ssr: false });

export default function LayoutWrapper({ children }) {
  // Kampagnen-Zuordnung beim ersten Laden im Arbeitsspeicher festhalten (keine Cookies)
  useEffect(() => herkunftErfassen(), []);

  // Info-Bildschirm (SCADA/TV): nur der Inhalt, ohne Kopf, Fuß, Banner und Widgets
  const pfad = usePathname() || "";
  if (pfad.startsWith("/portal")) return <main id="main-content">{children}</main>;

  return (
    <>
      {/* <GoogleTagManager gtmId="GTM-WR8PDT7V" /> */}
      <RevealObserver />
      {/* Cookie-Banner vor dem Seitenkopf: in der Tab-Reihenfolge direkt nach dem Sprunglink erreichbar (fixiert positioniert) */}
      <CookieComponentLazy />
      <Navbar />
      <main id="main-content">{children}</main>
      <Footer />
      <aside aria-label="Schnellzugriff">
        <MobileCta />
        <ToTopButtonLazy />
      </aside>
    </>
  );
}
"use client";

import { useId, useState } from "react";
import Link from "next/link";
import { ArrowRight, CheckCircle2, Loader2, LockKeyhole } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { herkunft } from "@/lib/herkunft";

/**
 * Einheitliches Anfrageformular aller Zielgruppen.
 *
 * Schickt an POST /api/anfrage → Vorgang im Backoffice. Wer sich später
 * mit derselben E-Mail registriert, sieht den Vorgang samt Status im Portal.
 *
 * Props:
 *  typ        flaeche | agri | investor | projekt | reststrom | energiegemeinschaft | genossenschaft | kommune | carport | speicher | kontakt
 *  daten      fachliche Zusatzdaten (z. B. Ergebnis eines Rechners) – werden mitgeschickt
 *  felder     zusätzliche Kontaktfelder: firma, telefon, plz, ort, land, nachricht
 *  titel/text/button/erfolgText  Beschriftungen
 *  dunkel     für Navy-Flächen
 */
export default function AnfrageFormular({
  typ = "kontakt",
  daten = {},
  felder = ["telefon", "nachricht"],
  titel,
  text,
  button = "Anfrage senden",
  erfolgText = "Danke! Ihre Anfrage ist eingegangen. Wir melden uns in der Regel innerhalb von zwei Werktagen.",
  rolle,
  className,
  dunkel = false,
}) {
  const id = useId();
  const [status, setStatus] = useState("offen"); // offen | sendet | fertig | fehler
  const [fehler, setFehler] = useState("");
  const [ergebnis, setErgebnis] = useState(null);

  async function absenden(e) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    if (fd.get("website")) return; // Honeypot
    const kontakt = {};
    for (const k of ["anrede", "vorname", "nachname", "firma", "email", "telefon", "plz", "ort", "land"]) {
      const v = fd.get(k);
      if (v) kontakt[k] = String(v).trim();
    }
    const nachricht = fd.get("nachricht");
    setStatus("sendet");
    setFehler("");
    try {
      const res = await fetch("/api/anfrage", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          typ,
          kontakt,
          daten: { ...daten, ...(nachricht ? { nachricht: String(nachricht) } : {}) },
          einwilligung: fd.get("einwilligung") === "on",
          herkunft: safeHerkunft(),
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok || !json.ok) throw new Error(json.error || "Senden fehlgeschlagen");
      setErgebnis(json);
      setStatus("fertig");
    } catch (err) {
      setFehler(err.message || "Senden fehlgeschlagen. Bitte versuchen Sie es erneut.");
      setStatus("fehler");
    }
  }

  const feld = cn(
    "block h-12 w-full rounded-xl px-4 text-[15px] outline-none transition-shadow placeholder:text-ink-400 focus-visible:ring-2 focus-visible:ring-ov-500",
    dunkel ? "bg-white/[0.07] text-white ring-1 ring-white/15 placeholder:text-white/40" : "bg-white text-ink-900 ring-1 ring-ink-200"
  );
  const label = cn("mb-1.5 block text-[13.5px] font-semibold", dunkel ? "text-white/85" : "text-ink-700");

  if (status === "fertig") {
    const registrieren = `/registrieren?${new URLSearchParams({ rolle: rolle || rolleFuerTyp(typ), vorgang: ergebnis?.id || "" })}`;
    return (
      <div role="status" className={cn("rounded-3xl p-7 md:p-9", dunkel ? "bg-white/[0.06] ring-1 ring-white/10" : "bg-ov-50 ring-1 ring-ov-200", className)}>
        <CheckCircle2 aria-hidden="true" className="h-9 w-9 text-ov-500" />
        <p className={cn("mt-4 font-display text-[22px] font-bold", dunkel ? "text-white" : "text-ink-900")}>Anfrage eingegangen</p>
        <p className={cn("mt-2 text-[15.5px] leading-relaxed", dunkel ? "text-white/75" : "text-ink-700")}>{erfolgText}</p>
        {ergebnis?.id && (
          <p className={cn("mt-3 text-[13.5px]", dunkel ? "text-white/55" : "text-ink-500")}>
            Vorgangsnummer <span className="ov-num font-semibold">{ergebnis.id}</span>
          </p>
        )}
        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
          <Link href={registrieren} className="inline-flex h-12 items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white hover:bg-ov-700">
            Status im Portal verfolgen <ArrowRight aria-hidden="true" className="h-4 w-4" />
          </Link>
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={absenden} noValidate={false} className={cn("space-y-4", className)} aria-describedby={titel ? `${id}-t` : undefined}>
      {titel && (
        <div>
          <p id={`${id}-t`} className={cn("font-display text-[22px] font-bold", dunkel ? "text-white" : "text-ink-900")}>{titel}</p>
          {text && <p className={cn("mt-1.5 text-[15px] leading-relaxed", dunkel ? "text-white/70" : "text-ink-600")}>{text}</p>}
        </div>
      )}
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label htmlFor={`${id}-vn`} className={label}>Vorname *</label>
          <input id={`${id}-vn`} name="vorname" required autoComplete="given-name" className={feld} />
        </div>
        <div>
          <label htmlFor={`${id}-nn`} className={label}>Nachname *</label>
          <input id={`${id}-nn`} name="nachname" required autoComplete="family-name" className={feld} />
        </div>
        {felder.includes("firma") && (
          <div className="sm:col-span-2">
            <label htmlFor={`${id}-fi`} className={label}>Unternehmen / Betrieb</label>
            <input id={`${id}-fi`} name="firma" autoComplete="organization" className={feld} />
          </div>
        )}
        <div className={felder.includes("telefon") ? "" : "sm:col-span-2"}>
          <label htmlFor={`${id}-em`} className={label}>E-Mail *</label>
          <input id={`${id}-em`} name="email" type="email" required autoComplete="email" className={feld} />
        </div>
        {felder.includes("telefon") && (
          <div>
            <label htmlFor={`${id}-te`} className={label}>Telefon</label>
            <input id={`${id}-te`} name="telefon" type="tel" autoComplete="tel" className={feld} />
          </div>
        )}
        {felder.includes("plz") && (
          <div>
            <label htmlFor={`${id}-plz`} className={label}>PLZ</label>
            <input id={`${id}-plz`} name="plz" inputMode="numeric" autoComplete="postal-code" className={feld} />
          </div>
        )}
        {felder.includes("ort") && (
          <div>
