      genossenschaft: "mitglied",
      energiegemeinschaft: "mitglied",
      kommune: "unternehmen",
    }[typ] || "flaeche"
  );
}

function safeHerkunft() {
  try {
    return herkunft() || undefined;
  } catch {
    return undefined;
  }
}
