150	import { useEffect, useRef, useState } from "react";
151	
152	/**
153	 * Zählt eine Zahl hoch, sobald sie sichtbar wird.
154	 * Server-HTML enthält bereits den Endwert (SEO, kein Layout-Sprung).
155	 */
156	export default function CountUp({ value, decimals = 0, duration = 1600, prefix = "", suffix = "", className }) {
157	  const ref = useRef(null);
158	  const ziel = Number(value) || 0;
159	  const [anzeige, setAnzeige] = useState(ziel);
160	
161	  useEffect(() => {
162	    const el = ref.current;
163	    if (!el) return;
164	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
165	
166	    let raf;
167	    const io = new IntersectionObserver(
168	      ([e]) => {
169	        if (!e.isIntersecting) return;
170	        io.disconnect();
171	        const start = performance.now();
172	        const schritt = (t) => {
173	          const p = Math.min((t - start) / duration, 1);
174	          const eased = 1 - Math.pow(1 - p, 4);
175	          setAnzeige(ziel * eased);
176	          if (p < 1) raf = requestAnimationFrame(schritt);
177	        };
178	        setAnzeige(0);
179	        raf = requestAnimationFrame(schritt);
180	      },
181	      { threshold: 0.4 }
182	    );
183	    io.observe(el);
184	    return () => {
185	      io.disconnect();
186	      cancelAnimationFrame(raf);
187	    };
188	  }, [ziel, duration]);
189	
190	  return (
191	    <span ref={ref} className={className ? `ov-num ${className}` : "ov-num"}>
192	      {prefix}
193	      {anzeige.toLocaleString("de-DE", { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}
194	      {suffix}
195	    </span>
196	  );
197	}
