              </Button>
            ) : (
              <>
                <Button variant="secondary" disabled={laeuft} onClick={() => weiter()}>Entwurf speichern</Button>
                <Button disabled={laeuft || fehlt.length > 0} onClick={einreichen} pfeil>
                  {laeuft ? "Wird eingereicht …" : "Zur Prüfung einreichen"}
                </Button>
              </>
            )}
          </div>
        </div>
      </form>
    </div>
  );
}

