                        { label: "Phase", wert: phase?.label },
                        { label: "Netz", wert: NETZANSCHLUSS[p.netzanschluss] },
                        { label: "Preis", wert: preisText(p) },
                        { label: "Beschreibung", wert: p.beschreibung, breit: true },
