await p.click('button[aria-label="Navigation öffnen"]');
await p.waitForTimeout(600);
await p.screenshot({ path: fileURLToPath(new URL("./shots/drawer.png", import.meta.url)) });
await p.click('text=Flächen-Pipeline >> visible=true');
await p.waitForURL("**/portal/admin/flaechen", { timeout: 120000 });
console.log("nav ok", p.url(), f);
await b.close();
EOF
